WITH valid AS (SELECT id, full_name, email, dept_id, job_title, salary, is_remote, level, DAYOFWEEK(hire_date) AS hire_date_dayofweek FROM employees WHERE hire_date > DATE '2023-04-23' AND job_title IS NOT NULL), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary, id) AS rn FROM valid QUALIFY rn = 1), with_dims AS (SELECT s.*, d.dept_name FROM deduped s LEFT JOIN departments d ON s.dept_id = d.id), grouped AS (SELECT CASE WHEN salary >= 142000 THEN 'LARGE' ELSE 'SMALL' END AS salary_tier, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list, PERCENTILE_APPROX(hire_date_dayofweek, ARRAY(0.25, 0.5, 0.75)) AS hire_date_dayofweek_quartiles, COUNT(*) FILTER (WHERE job_title = 'Manager') AS manager_rows FROM with_dims GROUP BY 1) SELECT salary_tier, job_title_list, hire_date_dayofweek_quartiles, manager_rows FROM grouped ORDER BY manager_rows DESC NULLS FIRST, salary_tier
